javascript:(()=>{const d=window.frames[5]?.document||document,c=(d.getElementById("commentsID")?.value||"").trim(),set=(id,val)=>{const e=d.getElementById(id);if(e)e.checked=val},clear=()=>d.querySelectorAll("input[type='checkbox'][id$='Id']").forEach(x=>{if(!["releaseonlyId","CON_CENTRALId","CON_EASTId","CON_WESTId"].includes(x.id))x.checked=false});if(/Shipment Contains (Watches|Clocks|Watch Parts)/i.test(c)){clear();const e=d.getElementById("entryTypeID");if(e)e.value="UNASSIGNED";set("HIGHRISKId",true);set("WATCHESId",true);set("releaseonlyId",false);console.log("WATCHES CASE")}else if(/Duplex Error|HOLD|Entry needs reset|cannot be resumed|not in proper status|system outage/i.test(c)){clear();set("HOLDId",true);console.log("HOLD CASE")}else if(/GN\s*-\s*Business Document/i.test(c)){clear();const e=d.getElementById("entryTypeID");if(e)e.value="GN";console.log("GN CASE")}else if(/Keyed 87\/01|Duplicate\s*-\s*Already processed/i.test(c)){clear();set("ECOMId",true);console.log("ECOM CASE")}else if(/^Review/i.test(c)){clear();set("REVIEWId",true);console.log("REVIEW CASE")}else console.log("NO MATCH:",c);})();
